"use client";

import { motion } from "motion/react";
import { useState } from "react";

export function ExpandableSearchTailwind({ width = 260 }) {
  const [open, setOpen] = useState(false);
  return (
    <motion.form
      role="search"
      onSubmit={(e) => e.preventDefault()}
      animate={{ width: open ? width : 44 }}
      transition={{ type: "spring", stiffness: 300, damping: 28 }}
      className="flex h-11 items-center overflow-hidden rounded-full border border-zinc-800 bg-zinc-900 text-zinc-100"
    >
      <button type="button" aria-label={open ? "Close search" : "Open search"} aria-expanded={open} onClick={() => setOpen(!open)} className="flex h-11 w-11 shrink-0 items-center justify-center text-zinc-400 hover:text-zinc-100">
        {open ? "×" : "⌕"}
      </button>
      {open && (
        <input autoFocus type="search" aria-label="Search" placeholder="Search components…" onKeyDown={(e) => e.key === "Escape" && setOpen(false)} className="w-full bg-transparent pr-4 text-sm outline-none placeholder:text-zinc-500" />
      )}
    </motion.form>
  );
}
